void main(){
  float m = clamp(u_motion, 0.0, 1.0);
  float ph = iProgress * 6.28318;
  vec2 q = uv;
  float asp = iResolution.x / max(iResolution.y, 1.0);
  vec2 w = vec2(sin(q.y * 3.1 + ph) + 0.6 * sin(q.y * 5.3 - ph * 0.5 + 1.7),
                cos(q.x * 2.7 - ph) + 0.6 * cos(q.x * 4.9 + ph * 0.5 + 0.9));
  w.x /= asp;
  q += w * 0.06 * m;
  vec2 c = vec2(0.5) + rot(ph * 0.25 * m) * (q - 0.5);
  vec2 f = smoothstep(0.0, 1.0, clamp(c, 0.0, 1.0));
  vec3 top = mix(u_topLeft, u_topRight, f.x);
  vec3 bot = mix(u_bottomLeft, u_bottomRight, f.x);
  vec3 col = mix(bot, top, f.y);
  col += (hash(uv * iResolution + float(iFrame)) - 0.5) / 255.0;
  fragColor = vec4(col, 1.0);
}
